def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_intervals = sorted(intervals, key=lambda iv: (iv[0], iv[1]))
    merged = [list(sorted_intervals[0])]
    for start, end in sorted_intervals[1:]:
        if start <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], end)
        else:
            merged.append([start, end])
    return merged

import heapq


def toposort(nodes, edges):
    nodes = list(nodes)
    edges = list(edges)

    indegree = {node: 0 for node in nodes}
    adj = {node: [] for node in nodes}

    for source, dest in set(edges):
        adj[source].append(dest)
        indegree[dest] += 1

    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Graph contains a cycle")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit must be a positive integer")
    for _, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("invalid weight")
    if not items:
        return []
    batches = []
    current = []
    current_weight = 0
    for name, weight in items:
        if current_weight + weight > limit:
            if current:
                batches.append(current)
            current = [name]
            current_weight = weight
        else:
            current.append(name)
            current_weight += weight
    if current:
        batches.append(current)
    return batches

import re


def parse_env(text):
    key_re = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    result = {}
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        key, sep, value = line.partition('=')
        if sep != '=':
            raise ValueError(f'invalid environment assignment: {raw!r}')
        key = key.strip()
        value = value.strip()
        if not key_re.match(key):
            raise ValueError(f'invalid key: {key!r}')
        if len(value) >= 2 and value[0] in ('"', "'") and value[-1] == value[0]:
            value = value[1:-1]
        result[key] = value
    return result

def parse_sse(chunks):
    data = b''.join(chunks).decode('utf-8')
    data = data.replace('\r\n', '\n')

    events = []
    current = []

    for line in data.split('\n'):
        if line == '':
            if current:
                text = '\n'.join(current)
                if text == '[DONE]':
                    return events
                events.append(text)
                current = []
        elif line.startswith('data:'):
            rest = line[5:]
            if rest.startswith(' '):
                rest = rest[1:]
            current.append(rest)

    return events

import math


def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("attempt, base, and cap must be nonnegative")
    # base == 0 makes the product 0; cap == 0 caps it at 0.
    if base == 0 or cap == 0:
        return 0.0
    # base > 0 and cap > 0 here.
    # base * 2**attempt == 2**(attempt + log2(base)).
    # Compare in log space so we never materialize 2**attempt (e.g. 2**(10**9)),
    # which would build a gigantic integer and overflow a float.
    if attempt + math.log2(base) >= math.log2(cap):
        return float(cap)
    # Here base * 2**attempt < cap <= max finite float, so the value is finite.
    # ldexp multiplies by 2**attempt using the binary exponent (no huge int),
    # and the result cannot overflow because it is strictly below cap.
    return math.ldexp(base, int(attempt))

def fifo_admit(active, queued, budget, slots):
    if any(res > budget for res in queued):
        raise ValueError("queued reservation exceeds the whole budget")

    admitted = []
    remaining_budget = budget - sum(active)
    remaining_slots = slots - len(active)

    for res in queued:
        if remaining_slots > 0 and res <= remaining_budget:
            admitted.append(res)
            remaining_budget -= res
            remaining_slots -= 1
        else:
            break  # never skip a blocked head request

    return admitted, queued[len(admitted):]
